OtaTaskSnapshot? get taskSnapshot => _publishedTaskSnapshot.value;
String? get taskDeviceAddress =>
    _taskKey?.generation == _ownerEpoch ? _taskDeviceAddress : null;
Stream<bool> get taskActivity => _isUpgrading.stream;

Future<DeviceOtaInfo?> readDeviceInfo(String deviceAddress) async {
  if (_isUpgrading.value) {
    // 升级进行中禁止重建 transport：_bindTransport 会 dispose
    // 在途 transport，打断传输（RC2-04）。返回现有快照。
    return _deviceInfo;
  }
  return _runExclusive((generation) async {
    _deviceInfo = null; // 先失效旧快照，成功才重建
    _deviceInfoAddress = null;

Future<T?> _runExclusive<T>(Future<T?> Function(int generation) body) async {
  if (_isUpgrading.value) {
    _notify('提示', '操作进行中，请先取消或等待完成');
    return null;
  }
  _isUpgrading.value = true;
  final done = Completer<void>();
  final previous = _ownerDone;
  final generation = _cancelGeneration;
  _ownerEpoch++; // 登记即前进（RC3-04⑤）：取消窗口用它识别后来者
  final epoch = _ownerEpoch;
  _ownerDone = done.future;
  try {
    await previous;
    // RC3-04：排队等待期间被取消（代次已变）则不进入 body——禁止
    // 执行已被取消的操作（如恢复下载 body 前不查取消导致取消后又
    // 发起请求）。
    if (generation != _cancelGeneration) return null;
    return await body(generation);
  } finally {
    final task = _taskKey;
    try {
      if (task != null && task.generation == epoch) await _finishBackgroundTask(task);
    } finally {
      if (!done.isCompleted) done.complete();
      if (identical(_ownerDone, done.future)) {
        _ownerDone = null;
        _isUpgrading.value = false;
      }
    }

/// 当前连接设备地址（GET_INFO/传输的入口；无连接则为 null）。
String? get _deviceAddress =>
    _attachedTaskAddress ??
    (widget.connectedDevice ?? _resolvedDevice)?.remoteId.str.toLowerCase();

bool get _deviceReady =>
    !_needsTaskReconcile && !_reconcilingTask &&
    _deviceAddress != null && otaService.deviceInfo != null;

_taskSub = otaService.taskActivity.listen((busy) {
  if (!mounted) return;
  if (busy) {
    _attachCurrentTask();
  } else if (_needsTaskReconcile && !_backgrounded) {
    unawaited(_resolveDeviceAndRead());
  }
});

Future<void> _resolveDeviceAndRead() async {
  // Reattach only: an active owner retains its transport and reboot probe.
  if (otaService.isUpgrading) {
    _attachCurrentTask();
    return;
  }
  if (_reconcilingTask || _backgrounded || !mounted) return;
  if (_needsTaskReconcile) {
    // Keep the owner's exact target, never the first unrelated connection.
    _needsTaskReconcile = false;
    setState(() { _reconcilingTask = true; });
    try {
      await _readDeviceInfo();
    } finally {
      if (mounted) setState(() { _reconcilingTask = false; });
    }
    return;
  }
  await _resolveConnectedDevice();
  await _readDeviceInfo();
}

void _attachCurrentTask() {
  final address = otaService.taskDeviceAddress;
  if (address == null) return;
  setState(() {
    _attachedTaskAddress = address;
    _resolvedDevice = BluetoothDevice.fromId(address);
    _needsTaskReconcile = true;
  });
}

Future<void> _readDeviceInfo() async {
  // 后台停写（RC3-08④）：后台期间不主动发起 GET_INFO 等 GATT
  // 操作，回前台时由生命周期回调统一重新读取。
  if (_backgrounded) return;
  await _resolveConnectedDevice();
  final address = _deviceAddress;
  if (address == null) return;
  await otaService.readDeviceInfo(address);
  if (mounted) setState(() {});
}

Widget _buildCheckUpdateButton() {
  // 终止闭锁与 service 层 _terminalLocked 对齐（RC3-12③）：非
  // retryableLater 的终止态下禁用检查入口（解锁入口是重新读取设备
  // 身份，而非盲目重查）；retryableLater（如重启重连失败）仍可查。
  final terminal = otaService.terminalState;
  final terminalLocked = terminal != null && !terminal.retryableLater;
  final canCheck = !_isChecking &&
      !otaService.isUpgrading &&
      otaService.isFirmwareServiceConfigured &&
      _deviceReady &&
      !terminalLocked;

for (final terminal in [OtaPhase.completed, OtaPhase.cancelled, OtaPhase.failed]) {
  testWidgets('P38-R04 notification page reattaches target after $terminal', (tester) async {
    final fake = _FakeOtaService()
      ..taskAddress = 'aa:bb:cc:dd:ee:ff'
      ..info = deviceInfoOf()
      ..readResult = deviceInfoOf();
    fake.isUpgrading$.value = true;
    fake.phase$.value = OtaPhase.transferring;
    await pumpPage(tester, fake: fake, settle: false);
    expect(fake.readCalls, 0, reason: 'a notification page is not a second BLE owner');
    expect(findButton(tester, '检查更新').onPressed, isNull);
    fake.readGate = Completer<void>();
    fake.phase$.value = terminal;
    fake.isUpgrading$.value = false;
    await tester.pump();
    expect(fake.readCalls, 1);
    expect(fake.lastReadAddress, 'aa:bb:cc:dd:ee:ff');
    expect(findButton(tester, '检查更新').onPressed, isNull,
        reason: 'cached identity must not enable actions before reconciliation');
    fake.readGate!.complete();
    await tester.pumpAndSettle();
    expect(findButton(tester, '检查更新').onPressed, isNotNull);
    expect(fake.readCalls, 1, reason: 'identity read completion must not loop');

bool get isUpgrading => isUpgrading$.value;
@override
Stream<bool> get taskActivity => isUpgrading$.stream;
@override
String? get taskDeviceAddress => taskAddress;

@override
Future<DeviceOtaInfo?> readDeviceInfo(String deviceAddress) async {
  readCalls++;
  lastReadAddress = deviceAddress;
  await readGate?.future;
  // 页面自动读取：返回值同时驱动连接卡状态。
  final result = readResult;
  if (result != null) {
    info = result;
    // 与真实 service 对齐（PR11 解锁）：读取成功清除终止态。
    terminal$.value = null;
  }
  return result;
}

